/**
 * Terraria / TShock version catalogue — PURE parsing + selection (no I/O), used by the mirror
 * sweep (worker/terraria-mirror.ts), the public version list (/api/terraria-versions), the
 * Settings picker and the update path.
 *
 * Sources, both public and read-only:
 *  - GitHub releases of Pryaxis/TShock: tag `v6.2.1`, publish date, notes, and the asset name
 *    `TShock-6.2.1-for-Terraria-1.4.5.8-linux-x64-Release.zip` = the Terraria version it targets.
 *  - the registry tag list of ghcr.io/pryaxis/tshock: which releases actually have an image.
 * An entry exists only if BOTH are true. Pre-releases (`6.0.0-pre3`) are never offered.
 * Only releases >= TERRARIA_MIN_OFFERED are listed (see lib/terraria-image.ts).
 *
 * Vanilla Terraria: the platform has no vanilla variant (the Terraria schema's only variant is
 * TShock, and every server is a TShock server), so there is nothing to catalogue for it.
 */
import { compareDotted, terrariaKnown } from "./terraria-image";

export const TERRARIA_MIN_OFFERED = "6.0.0";

export type TerrariaCatalogueEntry = {
  tshock: string;
  terraria: string;
  /** ISO date (published_at). */
  released: string;
  /** First line(s) of the release notes, plain text, <= 280 chars. */
  notes: string;
  /** Newest stable release with an image. Exactly one entry has it. */
  recommended: boolean;
  /** Image id / index digest when the platform has verified this release (TERRARIA_KNOWN_VERSIONS). */
  verified: boolean;
};

export type GithubRelease = {
  tag_name?: string;
  published_at?: string;
  prerelease?: boolean;
  draft?: boolean;
  body?: string | null;
  assets?: { name?: string }[];
};

const ASSET_RE = /^TShock-(\d+(?:\.\d+){1,3})-for-Terraria-(\d+(?:\.\d+){3})-linux-(?:x64|amd64)-Release\.zip$/;

/** "6.2" style versions in asset names are normalised to three parts ("5.2" -> "5.2.0") to match image tags. */
const norm = (v: string) => (v.split(".").length === 2 ? `${v}.0` : v);

export function plainNotes(body: string | null | undefined): string {
  const text = (body ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map((l) => l.replace(/^[#>*\-\s]+/, "").trim())
    .filter((l) => l && !/^notable changes/i.test(l))
    .join(" ")
    .replace(/\*\*|`|\[|\]\([^)]*\)/g, "");
  return text.length > 280 ? text.slice(0, 277) + "..." : text;
}

export function buildCatalogue(releases: GithubRelease[], imageTags: string[]): TerrariaCatalogueEntry[] {
  const tags = new Set(imageTags);
  const out: Omit<TerrariaCatalogueEntry, "recommended">[] = [];
  const seen = new Set<string>();
  for (const r of releases) {
    if (!r || r.draft || r.prerelease) continue;
    const tag = String(r.tag_name ?? "").replace(/^v/, "");
    if (!/^\d+\.\d+\.\d+$/.test(tag) || seen.has(tag)) continue;
    if (compareDotted(tag, TERRARIA_MIN_OFFERED) < 0) continue;
    if (!tags.has(tag)) continue; // no image for it
    let terraria: string | null = null;
    for (const a of r.assets ?? []) {
      const m = ASSET_RE.exec(a.name ?? "");
      if (m && norm(m[1]) === tag) {
        terraria = m[2];
        break;
      }
    }
    if (!terraria) terraria = terrariaKnown(tag)?.terraria ?? null;
    if (!terraria) continue; // cannot say which Terraria it targets -> do not offer
    seen.add(tag);
    out.push({
      tshock: tag,
