export async function withServerSsh<T>(
  server: SftpServer,
  fn: (conn: Client) => Promise<T>
): Promise<T> {
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password on record.");

  // Try the per-server management key first (see Server.sshManagementKeyEnc's
  // schema doc comment) — falls back to the password if there's no key on file
  // yet, or the key is present but the connect itself fails (e.g. a customer
  // deleted our line from their own authorized_keys). Only a CONNECT failure
  // triggers the fallback — once `fn` is running, its own errors propagate
  // normally rather than silently retrying the whole operation a second time.
  let conn: Client;
  if (privateKey) {
    try {
      conn = await connectOnce(target, { privateKey });
    } catch (e) {
      if (!password) throw e;
      conn = await connectOnce(target, { password });
    }
  } else {
    conn = await connectOnce(target, { password: password! });
  }

  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

