/**
 * Terraria version drift REPORT (report only: nothing here ever changes a server).
 * For each RUNNING Terraria server: read-only `docker inspect` + `docker logs --tail` over SSH, then
 * compare the image/log versions with the platform's recommended version (mirror catalogue, else the
 * pinned one). Output: console lines + `<mirror root>/drift.json` (read by scripts/terraria-drift-report.ts
 * and the admin). Updating is always a deliberate GAME_UPDATE job (docs: "Terraria image update").
 */
import fs from "node:fs/promises";
import path from "node:path";
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { withServerSsh } from "../lib/ssh-exec";
import { TERRARIA_PINNED_VERSION, type DriftRow } from "../lib/terraria-image";
import { readTerrariaIndex, terrariaMirrorRoot } from "../lib/terraria-mirror";
import { sshGuest } from "./terraria-guest";
import { inspectTerrariaDrift } from "./terraria-update";

export type DriftReportRow = DriftRow & { serverId: string; hostname: string };
export type DriftReport = { at: string; wanted: string; rows: DriftReportRow[]; behind: number };

export async function terrariaDriftReport(): Promise<DriftReport> {
  const ix = await readTerrariaIndex().catch(() => null);
  const wanted = Object.values(ix?.versions ?? {}).find((v) => v.recommended)?.tshock ?? TERRARIA_PINNED_VERSION;
  const servers = await db.server.findMany({
    where: { status: "RUNNING", osTemplate: { family: "terraria" } },
    include: { osTemplate: true, dedicatedIp: true, node: true },
  });
  const rows: DriftReportRow[] = [];
  for (const s of servers) {
    try {
      const row = await withServerSsh(s as never, (conn) => inspectTerrariaDrift(sshGuest(conn), wanted));
      rows.push({ ...row, serverId: s.id, hostname: s.hostname });
    } catch (e) {
      rows.push({ status: "unknown", configured: null, logged: null, wanted, detail: `could not read: ${e instanceof Error ? e.message.slice(0, 120) : "error"}`, serverId: s.id, hostname: s.hostname });
    }
  }
  const report: DriftReport = { at: new Date().toISOString(), wanted, rows, behind: rows.filter((r) => r.status === "legacy" || r.status === "behind").length };
  try {
    await fs.writeFile(path.join(terrariaMirrorRoot(), "drift.json"), JSON.stringify(report, null, 2));
  } catch {
    /* mirror dir absent: console only */
  }
  return report;
}

/** Scheduler hook. Read-only; set TERRARIA_DRIFT_SWEEP=off to disable. */
export async function terrariaDriftSweep(): Promise<void> {
  if (SANDBOX || process.env.TERRARIA_DRIFT_SWEEP === "off") return;
  const r = await terrariaDriftReport();
  if (!r.rows.length) return;
  console.log(`[terraria-drift] wanted TShock ${r.wanted}: ${r.rows.length} server(s), ${r.behind} behind`);
  for (const row of r.rows) if (row.status !== "current") console.log(`[terraria-drift]   ${row.hostname}: ${row.status} (${row.detail})`);
}

