import type { Client } from "ssh2";
import { exec, execInput } from "../lib/ssh-exec";
import type { Guest } from "./game-config-appliers/types";
import { shq } from "./game-config-appliers/types";

/** A `Guest` over an open SSH connection (exec + cat/stdin file I/O; no SFTP needed). */
export function sshGuest(conn: Client): Guest {
  return {
    async exec(cmd, timeoutMs = 120_000) {
      const r = await exec(conn, cmd, timeoutMs);
      return { code: r.code ?? 1, stdout: r.stdout, stderr: r.stderr };
    },
    async readFile(path) {
      const r = await exec(conn, `test -f ${shq(path)} && cat ${shq(path)}`, 30_000);
      return r.code === 0 ? r.stdout : null;
    },
    async writeFile(path, content) {
      const r = await execInput(conn, `cat > ${shq(path)}`, content, 60_000);
      if (r.code !== 0) throw new Error("write failed");
    },
  };
}

