 * the admins — once per spell. Auto-restart only when enabled (per-server flag
 * or GAME_AUTO_RESTART=1; both default OFF), at most once per hour per server.
 * Skips servers with a job in flight (their state is changing under us).
 */
export async function gameRuntimeSweep(): Promise<void> {
  const servers = (await db.server.findMany({
    where: { status: "RUNNING", OR: [{ gamePlanId: { not: null } }, { osTemplate: { family: { in: [...GAME_FAMILIES] } } }] },
    select: RUNTIME_SERVER_SELECT,
  })) as unknown as RuntimeServer[];

  const candidates = servers.filter((s) => familyOf(s));
  if (candidates.length === 0) return;
  const busyRows = await db.job.findMany({
    where: { serverId: { in: candidates.map((s) => s.id) }, status: { in: ["QUEUED", "RUNNING"] } },
    select: { serverId: true },
  });
  const busy = new Set(busyRows.map((b) => b.serverId));

  let down = 0;
  await mapLimit(candidates, SWEEP_CONCURRENCY, async (server) => {
    if (busy.has(server.id)) return;
    const now = new Date();
    const r = await probeGameRuntime(server, { now });
    if (!r) return;
    await saveRuntime(server.id, r, now);

    const row = await db.gameRuntime.findUnique({
      where: { serverId: server.id },
      select: { intent: true, downSince: true, alertedAt: true, lastAutoRestartAt: true, autoRestart: true },
    });
    const d = sweepDecision({
      state: r.state,
      intent: (row?.intent as RunIntent | null) ?? null,
      downSince: row?.downSince ?? null,
      alertedAt: row?.alertedAt ?? null,
      lastAutoRestartAt: row?.lastAutoRestartAt ?? null,
      autoRestartEnabled: GLOBAL_AUTO_RESTART || !!row?.autoRestart,
      now,
    });
    if (d.downSince) down++;
    await db.gameRuntime.update({
      where: { serverId: server.id },
      data: {
        downSince: d.downSince,
        ...(d.clearAlert ? { alertedAt: null } : {}),
        ...(d.alert ? { alertedAt: now } : {}),
        ...(d.autoRestart ? { lastAutoRestartAt: now } : {}),
      },
    });

    if (d.alert) {
      const mins = Math.round((now.getTime() - (d.downSince ?? now).getTime()) / 60_000);
      const label = runtimeLabel(r.state).label;
      await notifyAdmins(
        `Game down: ${server.hostname} (${label}) for ${mins}+ min`,
        `${server.hostname} (${r.family}, ${server.node?.name ?? "?"}) — VM is running but the game is "${label}" ` +
          `and nobody stopped it on purpose. service=${r.probe.service ?? "?"} container=${r.probe.containerState ?? "?"} ` +
          `portBound=${String(r.portBound)} external=${String(r.externalOk)}${r.externalTarget ? ` (${r.externalTarget})` : ""}` +
          `${r.error ? ` probeError=${r.error}` : ""}. ` +
          (GLOBAL_AUTO_RESTART || row?.autoRestart ? "Auto-restart is ON for this server." : "Auto-restart is off (alert only)."),
        `/admin/servers/${server.id}`
      ).catch((e) => console.error("[game-runtime] admin alert failed", e));
      await db.auditLog
        .create({ data: { userId: null, action: "gameserver.runtime.down_alert", detail: `${server.hostname} state=${r.state} for ${mins}m` } })
        .catch(() => {});
    }
    if (d.autoRestart) {
      const inflight = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
      if (inflight === 0) {
        const action = r.state === "game_stopped" ? "start" : "restart";
        await db.job.create({
          data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: false, source: "auto-restart" } },
        });
        await db.auditLog
          .create({ data: { userId: null, action: "gameserver.runtime.auto_restart", detail: `${server.hostname} ${action} (state=${r.state})` } })
          .catch(() => {});
      }
    }
  });
  if (down > 0) console.log(`[game-runtime] sweep: ${candidates.length} game server(s) probed, ${down} down without a stop on record`);
}

